      "vs_h2": "引き継ぎ vs ファウンドリ開始",
      "vs": "既存レガシー鯖の編成を残したいならSTOVE→Steamログインを変換。ファウンドリ開始はお祝いバフと別PvPを持つファウンドリキャラを育てることで、ログイン変換だけではレガシー後継者は移りません。手順は次を参照：",
      "link_transfer": "STOVE ↔ Steam引き継ぎ",
      "link_rabbit": "シークレットラビット♥ホール",
      "link_quests": "クエストハブ",
      "link_faq": "FAQ",
      "link_download": "Steamダウンロードチェック",
