      "vs_h2": "Transferir vs. começar no Foundry",
      "vs": "Converta o login STOVE→Steam quando quiser manter um elenco existente do servidor legado. Começar no Foundry significa criar/jogar com um personagem do Foundry, com buffs de celebração e PvP separado — só a transferência nunca move um Herdeiro legado para o Foundry. Leia os passos completos de transferência em",
      "link_transfer": "Transferência STOVE ↔ Steam",
