      "answer": "파운드리 퀘스트는 새 트랙입니다 — 로그인 이전 후 레거시 에피소드/일일/주간 체크를 상속하지 않습니다. 시한 파운드리 미션을 먼저 처리한 뒤 그 캐릭의 일일/주간을 돌리세요. 날짜형 해금은 [[파운드리 서버 가이드|/foundry/#server-guide]]와 [[파운드리 길드전|/foundry/#guild-war]]에 있습니다. 비공식 — STOVE 인용.",
