        "Event-Dailies, solange sie laufen (z. B. Great Detective Daily Investigation bringt Punkte fürs Lucky Board).",
        "Freundschafts-/Geschenk-Dailies halten Support-Einheiten in Bewegung, ohne riesige Stamina-Kosten.",
